/**
 * src/lib/studio/streamStudioClient.ts
 *
 * Client-side helper for progressive NDJSON studio parsing.
 * Streams partial script events as they are generated by the LLM
 * and resolves with the final validated StudioPayload.
 *
 * Supports both streaming (application/x-ndjson) and non-streaming (application/json)
 * responses for backward compatibility and test mock safety.
 */

import type { StudioType, StudioPayload } from "./parsers/types";
import { computeSceneCount } from "./parsers/stream";

export interface StreamStudioParseOptions {
  storyId: string;
  studioType: StudioType;
  personaSlugs?: string[];
  personaSlug?: string;
  participantCount?: 2 | 3;
  layoutKey?: string;
  provider?: "gemini" | "ollama";
  model?: string;
  allowFallback?: boolean;
  onPartial?: (partial: Record<string, unknown>, sceneCount: number) => void;
  signal?: AbortSignal;
}

export interface StreamStudioParseResult<TPayload = StudioPayload> {
  studioType: StudioType;
  storyId: string;
  storyTitle: string;
  payload: TPayload;
}

export async function streamStudioParse<TPayload = StudioPayload>(
  options: StreamStudioParseOptions
): Promise<StreamStudioParseResult<TPayload>> {
  const {
    storyId,
    studioType,
    personaSlugs,
    personaSlug,
    participantCount,
    layoutKey,
    provider,
    model,
    allowFallback,
    onPartial,
    signal,
  } = options;

  const res = await fetch(`/api/stories/${storyId}/parse-studio`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      studioType,
      personaSlugs,
      personaSlug,
      participantCount,
      layoutKey,
      provider,
      model,
      allowFallback,
      stream: true,
    }),
    signal,
  });

  if (!res.ok) {
    let errMsg = `Failed to parse article for studio (${res.status})`;
    try {
      const errJson = await res.json();
      if (errJson?.details || errJson?.error) {
        errMsg = errJson.details || errJson.error;
      }
    } catch {
      // Fall through to status error
    }
    throw new Error(errMsg);
  }

  const contentType = res.headers.get("content-type") || "";

  // Fallback if the response is not an NDJSON stream (e.g. mock fetch in unit tests or legacy route)
  if (!contentType.includes("application/x-ndjson") || !res.body) {
    const data = await res.json();
    if (data.payload && onPartial) {
      const sceneCount = Math.max(
        1,
        computeSceneCount(studioType, (data.payload || {}) as Record<string, unknown>)
      );
      onPartial(data.payload as Record<string, unknown>, sceneCount);
    }
    return {
      studioType: data.studioType || studioType,
      storyId: data.storyId || storyId,
      storyTitle: data.storyTitle || "",
      payload: data.payload as TPayload,
    };
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder("utf-8");
  let buffer = "";
  let finalResult: StreamStudioParseResult<TPayload> | null = null;

  const processLine = (lineStr: string) => {
    const trimmed = lineStr.trim();
    if (!trimmed) return;
    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      if (finalResult) return;
      throw new Error(`Invalid streaming JSON line: ${trimmed.slice(0, 100)}`);
    }

    if (parsed.type === "partial") {
      onPartial?.(
        (parsed.partial as Record<string, unknown>) || {},
        (parsed.sceneCount as number) ?? 0
      );
    } else if (parsed.type === "complete") {
      finalResult = {
        studioType: (parsed.studioType as StudioType) || studioType,
        storyId: (parsed.storyId as string) || storyId,
        storyTitle: (parsed.storyTitle as string) || "",
        payload: parsed.payload as TPayload,
      };
    } else if (parsed.type === "error") {
      throw new Error((parsed.error as string) || "Streaming parser error");
    }
  };

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      // Leave the last (possibly incomplete) piece in the buffer
      buffer = lines.pop() ?? "";

      for (const line of lines) {
        processLine(line);
      }
    }

    // Flush any pending multi-byte sequence
    buffer += decoder.decode();

    // Process any leftover trailing line
    if (buffer.trim()) {
      processLine(buffer.trim());
    }
  } finally {
    reader.releaseLock();
  }

  if (!finalResult) {
    throw new Error("Stream closed without producing a complete studio payload");
  }

  return finalResult;
}
